#!/usr/bin/env node
/* MVP Trainer V5 R7.9 - Dimensional Futuristic Control System installer */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const root = process.cwd();
const target = path.join(root, "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedCurrentSha256 = "fcb25114f30bf434d7a70a60c40bc62e6d256e497dd792447fce993f6341bdae";
const expectedReplacementSha256 = "b6017b69db3f3e018863f09f7442c2f440529e814e9a49798f40619170bd56d5";
const replacementBase64 = "";

function sha256(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}
function fail(message) {
  console.error(`\nR7.9 STOPPED: ${message}\n`);
  process.exit(1);
}
if (!fs.existsSync(target)) {
  fail(`Could not find ${path.relative(root, target)}. Run this from the MVP Trainer repo root.`);
}
const current = fs.readFileSync(target);
const currentText = current.toString("utf8");
const currentSha = sha256(current);
if (currentText.includes("MVP_TRAINER_V5_R7_9_DIMENSIONAL_FUTURISTIC_CONTROL_SYSTEM")) {
  console.log("\nMVP Trainer V5 R7.9 is already applied. No files changed.\n");
  process.exit(0);
}
if (!currentText.includes("export function MusicMiniPlayer")) {
  fail("The target file does not look like the MVP MusicMiniPlayer. Nothing was changed.");
}
if (currentSha !== expectedCurrentSha256) {
  fail(
    "MusicMiniPlayer.tsx does not exactly match the R7.8 baseline this update was built against. " +
    "Nothing was overwritten. Send the current MusicMiniPlayer.tsx if you intentionally changed it after R7.8."
  );
}
const replacement = Buffer.from(replacementBase64, "base64");
if (sha256(replacement) !== expectedReplacementSha256) {
  fail("Replacement integrity check failed. Nothing was changed.");
}
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backup = `${target}.bak-r7-9-${stamp}`;
fs.copyFileSync(target, backup);
fs.writeFileSync(target, replacement);
console.log("\nMVP Trainer V5 R7.9 Dimensional Futuristic Control System applied successfully.");
console.log(`Updated: ${path.relative(root, target)}`);
console.log(`Backup:  ${path.relative(root, backup)}`);
console.log(`SHA-256: ${expectedReplacementSha256}`);
console.log("\nNext: run npm run build, then test desktop + mobile before committing.\n");
